const seq = !docked || nonzero ? inputSender.shouldSend(now, shipInputKey(input)) : null;
if (seq !== null) {
  clientRef.current?.send('input', shipInputToPayload(seq, input));
  p.step(dt, now, { seq, input });
} else if (!docked) {
  p.step(dt, now);
}
```

So, while docked, a frame is only sent when the input is nonzero. If the user presses W (thrust = 1), `nonzero` becomes true, and `inputSender.shouldSend(now, shipInputKey(input))` is called.

Next, `shouldSend`:

```js
shouldSend(nowMs: number, key: string): number | null {
  if (key === this.lastKey && nowMs - this.lastSendMs < INPUT_SEND_PERIOD_MS) return null;
  this.seqValue += 1;
  this.lastKey = key;
  this.lastSendMs = nowMs;
  return this.seqValue;
}
```

A frame is due when the key has changed, or when the last send was at least 50ms ago.

